/* ══════════════════════════════════════════════════════
   MAGNETIC BUTTON WRAPPER
══════════════════════════════════════════════════════ */
function Magnetic({ children, strength = 0.28, className = "" }) {
  const lite = useLite();
  const ref = useRef(null);
  const x = useMotionValue(0), y = useMotionValue(0);
  const sx = useSpring(x, { stiffness: 140, damping: 14, mass: 0.1 });
  const sy = useSpring(y, { stiffness: 140, damping: 14, mass: 0.1 });
  if (lite) return <span className={`inline-block ${className}`}>{children}</span>;
  return (
    <motion.div ref={ref} className={`inline-block ${className}`} style={{ x: sx, y: sy }}
      onMouseMove={e => {
        const r = ref.current.getBoundingClientRect();
        x.set((e.clientX - r.left - r.width / 2) * strength);
        y.set((e.clientY - r.top - r.height / 2) * strength);
      }}
      onMouseLeave={() => { x.set(0); y.set(0); }}>
      {children}
    </motion.div>
  );
}

/* ══════════════════════════════════════════════════════
   3D TILT CARD
══════════════════════════════════════════════════════ */
function TiltCard({ children, className = "" }) {
  const lite = useLite();
  const ref = useRef(null);
  const mx = useMotionValue(0), my = useMotionValue(0);
  const rotX = useTransform(my, [-120, 120], [9, -9]);
  const rotY = useTransform(mx, [-120, 120], [-9, 9]);
  const srX = useSpring(rotX, { stiffness: 220, damping: 28 });
  const srY = useSpring(rotY, { stiffness: 220, damping: 28 });
  if (lite) return <div className={className}>{children}</div>;
  return (
    <motion.div ref={ref} className={className}
      style={{ rotateX: srX, rotateY: srY, transformPerspective: 1100, transformStyle: "preserve-3d" }}
      onMouseMove={e => {
        const r = ref.current.getBoundingClientRect();
        mx.set(e.clientX - r.left - r.width / 2);
        my.set(e.clientY - r.top - r.height / 2);
      }}
      onMouseLeave={() => { mx.set(0); my.set(0); }}>
      {children}
    </motion.div>
  );
}

/* ══════════════════════════════════════════════════════
   FLOATING PARTICLES
══════════════════════════════════════════════════════ */
function Particles({ count = 28 }) {
  const lite = useLite();
  const [pts] = useState(() =>
    Array.from({ length: count }, (_, i) => {
      const s = ((i * 2654435761) & 0xffffffff) >>> 0;
      return {
        id: i,
        x: ((s & 0xfff) / 0xfff) * 100,
        y: (((s >> 12) & 0xfff) / 0xfff) * 100,
        sz: (((s >> 24) & 0xf) / 0xf) * 1.8 + 0.5,
        op: (((s >> 8) & 0xff) / 0xff) * 0.18 + 0.04,
        dur: ((((s >> 16) & 0xff) / 0xff) * 12 + 9).toFixed(1),
        del: (-(((s >> 20) & 0xff) / 0xff) * 20).toFixed(1),
      };
    })
  );
  if (lite) return null;
  return (
    <div className="absolute inset-0 pointer-events-none overflow-hidden" aria-hidden="true">
      {pts.map(p => (
        <div key={p.id} className="absolute rounded-full bg-white"
          style={{ left:`${p.x}%`, top:`${p.y}%`, width:`${p.sz}px`, height:`${p.sz}px`,
            opacity: p.op, animation:`particle-float ${p.dur}s ${p.del}s ease-in-out infinite` }} />
      ))}
    </div>
  );
}

/* ══════════════════════════════════════════════════════
   MOUSE GLOW
══════════════════════════════════════════════════════ */
function MouseGlow() {
  const lite = useLite();
  const x = useMotionValue(-400), y = useMotionValue(-400);
  const sx = useSpring(x, { stiffness: 70, damping: 18 });
  const sy = useSpring(y, { stiffness: 70, damping: 18 });
  useEffect(() => {
    if (lite) return;
    const fn = e => { x.set(e.clientX); y.set(e.clientY); };
    window.addEventListener("mousemove", fn, { passive: true });
    return () => window.removeEventListener("mousemove", fn);
  }, [x, y, lite]);
  if (lite) return null;
  return (
    <motion.div className="pointer-events-none fixed z-0"
      style={{ left: sx, top: sy, width: 600, height: 600, x:"-50%", y:"-50%",
        background:"radial-gradient(circle, rgba(89,130,250,0.06) 0%, transparent 65%)", borderRadius:"50%" }} />
  );
}

/* ══════════════════════════════════════════════════════
   REVEAL
══════════════════════════════════════════════════════ */
function Reveal({ children, delay = 0, className = "" }) {
  const ref = useRef(null);
  const inView = useInView(ref, { once: true, amount: 0.1 });
  return (
    <motion.div ref={ref} className={className}
      initial={{ opacity: 0, y: 36 }}
      animate={inView ? { opacity: 1, y: 0 } : {}}
      transition={{ duration: 0.8, delay, ease: EASE }}>
      {children}
    </motion.div>
  );
}

