function Counter({ to, suffix = "" }) {
  const [v, setV] = useState(0);
  const ref = useRef(null);
  const inView = useInView(ref, { once: true });
  useEffect(() => {
    if (!inView) return;
    let n = 0; const step = to / 55;
    const t = setInterval(() => { n += step; if (n >= to) { setV(to); clearInterval(t); } else setV(Math.floor(n)); }, 24);
    return () => clearInterval(t);
  }, [inView, to]);
  return <span ref={ref}>{v}{suffix}</span>;
}

/* ══════════════════════════════════════════════════════
   SYNTAX HIGHLIGHT
══════════════════════════════════════════════════════ */
function hlSQL(r) {
  return r.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;")
    .replace(/(--[^\n]*)/g,`<span style="color:${CAT.overlay0};font-style:italic">$1</span>`)
    .replace(/\b(SELECT|FROM|WHERE|GROUP\s+BY|ORDER\s+BY|SUM|COUNT|AVG|DESC|ASC|LIMIT|AND|OR|ON|AS|JOIN|LEFT|RIGHT|INNER|INSERT|INTO|UPDATE|SET|DELETE|CREATE|TABLE|VIEW|DROP|DISTINCT|HAVING)\b/g,`<span style="color:${CAT.blue}">$1</span>`)
    .replace(/('(?:[^'\\]|\\.)*')/g,`<span style="color:${CAT.green}">$1</span>`)
    .replace(/\b(\d+\.?\d*)\b/g,`<span style="color:${CAT.peach}">$1</span>`);
}
function hlPY(r) {
  return r.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;")
    .replace(/(#[^\n]*)/g,`<span style="color:${CAT.overlay0};font-style:italic">$1</span>`)
    .replace(/\b(import|from|def|class|return|if|else|for|in|as|with|True|False|None|and|or|not)\b/g,`<span style="color:${CAT.mauve}">$1</span>`)
    .replace(/\b(pd|np|plt|px|go|duck|df|result|fig)\b/g,`<span style="color:${CAT.blue}">$1</span>`)
    .replace(/('(?:[^'\\]|\\.)*'|"(?:[^"\\]|\\.)*")/g,`<span style="color:${CAT.green}">$1</span>`)
    .replace(/\b(\d+\.?\d*)\b/g,`<span style="color:${CAT.peach}">$1</span>`);
}

