function CopyEmailButton() {
  const [copied, setCopied] = useState(false);
  const onCopy = e => {
    // allow meta/ctrl/right-click to still open mail client
    if (e.metaKey || e.ctrlKey) return;
    e.preventDefault();
    if (navigator.clipboard) navigator.clipboard.writeText(P.email);
    setCopied(true);
    setTimeout(() => setCopied(false), 1800);
  };
  return (
    <Magnetic>
      <a href={`mailto:${P.email}`} onClick={onCopy}
        className="group relative inline-flex items-center gap-2 rounded-full bg-white px-9 py-4 text-sm font-semibold text-black shadow-[0_0_50px_rgba(255,255,255,0.12)] transition-all hover:shadow-[0_0_80px_rgba(255,255,255,0.25)] hover:scale-105">
        <AnimatePresence mode="wait">
          {copied ? (
            <motion.span key="c" initial={{ y:8, opacity:0 }} animate={{ y:0, opacity:1 }} exit={{ y:-8, opacity:0 }}
              transition={{ duration:0.25 }} className="flex items-center gap-2">
              <CheckCircle2 className="h-4 w-4 text-green-500" /> Email copied
            </motion.span>
          ) : (
            <motion.span key="e" initial={{ y:8, opacity:0 }} animate={{ y:0, opacity:1 }} exit={{ y:-8, opacity:0 }}
              transition={{ duration:0.25 }} className="flex items-center gap-2">
              <Mail className="h-4 w-4" /> Email me
              <ArrowUpRight className="h-3.5 w-3.5 opacity-25 transition group-hover:opacity-100 group-hover:translate-x-0.5 group-hover:-translate-y-0.5" />
            </motion.span>
          )}
        </AnimatePresence>
      </a>
    </Magnetic>
  );
}

